                //---------------------------------------------------------------------
                NactiData() {
                    var that = this;
                    that.isl.MzaMonitorZakazek.detail({
                        data: { ixs_zak: this.detailDto.zakladniInformace.ixs_zak },
                        fragments: ["minimum", "ostatni"]
                    })
                        .getData()
                        .then(function (detail) {
                        that.detailDto = detail;
                        if (that.finChanged)
                            that.load({ data: that.detailDto, isChanged: that.isChanged });
                        else {
                            that.findFields().gfield("model", "apply", that.detailDto, { setFlags: { valid: false } });
                        }
                    });
                }
                //---------------------------------------------------------------------
                closing() {
                    var that = this;
                    this.isContentOpened = false;
                    return $.Deferred().resolve({ isChanged: this.isChanged }).promise().always(function () {
                        that.element.off('.mza');
                    });
                }
