                //---------------------------------------------------------------------
                aktualizuj() {
                    var that = this;
                    var data = this.grid.ggrid("getSelection");
                    this.actions.actAktualizujVZ.enabled(false);
                    var param = [];
                    let requestList = {};
                    that.notification("add", { title: "Zahájena aktualizace vybraných zakázek" }, true, true);
                    for (let i = 0, I = data.length; i < I; i++) {
                        let inp = { zobrazitData: 0, zpracovatData: 1, stahnoutData: 1, aktualizace: 1, id_nen: data[i].id_nen_tsez, ixs_zak: data[i].ixs_zak };
                        let def = $.Deferred();
                        Gordic.Async.GTaskManager.delayedStart("Gordic.Pap.Server.GAktualizaceNen", inp);
                        //asynchronní volání
                        param.push(def.promise());
                        requestList[data[i].ixs_zak] = def;
                    }
                    Gordic.Async.GTaskManager.on("done.aktualizaceNen", "Gordic.Pap.Server.GAktualizaceNen", (ctx, obj) => {
                        requestList[ctx.result.navrat.hlavicka].resolve(ctx.result);
                    })
                        .on("fail.aktualizaceNen", "Gordic.Pap.Server.GAktualizaceNen", function (o, exc) {
                        Gordic.Async.GTaskManager.off(".aktualizaceNen");
                        this.clean();
                        throw new GError("Chyba při aktualizaci Nen");
                    })
                        .on("always.aktualizaceNen", "Gordic.Pap.Server.GAktualizaceNen", function () {
                        this.clean();
                    });
                    $.when.apply(null, param).always(() => {
                        let l_ok = 0;
                        let defStart = $.Deferred();
                        let def;
                        for (let i = 0; i < param.length; i++) {
                            if (i === 0) {
                                def = defStart.promise();
                            }
                            def = def.then((data) => {
                                return param[i].then((result) => {
                                    // var def0 = $.Deferred();
                                    if (result.navrat.ok) {
                                        return that.isl.MzaMonitorZakazek.list({ ixs_zak: result.navrat.hlavicka }).getData().then(function (retVal) {
                                            data.push($.extend(retVal[0], { errorMsg: "" }));
                                            l_ok++;
                                            return data;
                                        });
                                    }
                                    else {
                                        data.push({ ixs_zak: result.navrat.hlavicka, errorMsg: result.navrat.hlas });
                                        return data;
                                    }
                                    //def0.then(function ()
                                    //{
                                    //    return data;
                                    //})
                                }, (reason) => {
                                    //               data.push({ id_nen_tsez: result.navrat!.hlavicka, errorMsg: "Neznámá chyba" });
                                    return data;
                                });
                            });
                        }
                        defStart.resolve([]);
                        def.then((data) => {
                            if (that.isContentOpened) {
                                this.grid.ggrid("getView").updateData(data, "extend");
                                this.actions.actAktualizujVZ.enabled(true);
                            }
                            that.notification("add", { title: "Proběhla aktualizace vybraných zakázek - celkem/úspěšně : " + param.length.toString() + "/" + l_ok.toString(), state: "success" }, true, true);
                        });
                        Gordic.Async.GTaskManager.off(".aktualizaceNen");
                    });
                }
                //---------------------------------------------------------------------
